             boolean cancel = ask.get(WAIT_FOR_UI_MS, TimeUnit.MILLISECONDS);
             if (cancel) GesherWebView.log("shouldOverrideUrlLoading took " + appUrl);
+            if (!cancel && appUrl != null && appUrl.startsWith("intent:")) {
